@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{--ink:#eeeadf;--muted:#a19b91;--gold:#e4b979;--line:rgba(225,200,153,.22);--panel:rgba(20,19,25,.89)}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#100f19;color:var(--ink);font-family:'DM Sans',sans-serif}body{overflow:hidden}button,input{font:inherit}button{color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:#14121b}#scene{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges;background:#17141c}.grain{pointer-events:none;position:absolute;inset:0;z-index:2;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.screen{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;justify-content:space-between;padding:27px clamp(28px,6.1vw,94px) 23px;background:linear-gradient(90deg,rgba(13,12,17,.83) 0%,rgba(13,12,17,.67) 34%,rgba(13,12,17,.13) 70%,rgba(13,12,17,.08) 100%),linear-gradient(0deg,rgba(13,12,17,.72),transparent 25%,transparent 73%,rgba(13,12,17,.3));transition:opacity .7s ease,visibility .7s}.screen.leaving{opacity:0;visibility:hidden}.brand{display:flex;align-items:center;gap:12px;color:#e4c18c;font:500 10px 'DM Mono',monospace;letter-spacing:.16em}.brand-mark{font-size:19px;color:#f2c77f}.brand i{font-style:normal;color:#928c83;font-size:8px}.brand-line{width:37px;height:1px;background:#ae8d5a;margin:0 2px}.brand-small{font-size:8px;color:#a6a097;letter-spacing:.19em}.title-copy{position:absolute;top:15.5%;left:clamp(28px,6.1vw,94px);pointer-events:none}.eyebrow{font:500 9px 'DM Mono',monospace;letter-spacing:.19em;color:#d4ad74;margin:0 0 12px}.title-copy .eyebrow span{display:inline-block;width:5px;height:5px;background:#e4b979;border-radius:50%;margin:0 7px 1px 0;box-shadow:0 0 11px #e4b979}.title-copy h1{font:normal clamp(40px,6vw,74px)/.93 'Marcellus',Georgia,serif;letter-spacing:.07em;margin:0;color:#f1eee5;text-shadow:0 3px 22px #100f19}.title-copy h1 span{display:block;color:#dbb57c}.subtitle{font:normal 16px 'Marcellus',Georgia,serif;letter-spacing:.24em;color:#e8d8ba;margin:12px 0 14px}.intro{font-size:12px;line-height:1.75;color:#b5aea2;margin:0}.creator-panel{position:absolute;left:clamp(28px,6.1vw,94px);bottom:8.5%;width:min(485px,calc(100vw - 56px));padding:20px 22px 15px;background:linear-gradient(135deg,rgba(26,25,31,.94),rgba(17,17,23,.9));border:1px solid rgba(216,184,133,.25);box-shadow:0 18px 65px #08080bbd;backdrop-filter:blur(8px)}.creator-panel:before,.creator-panel:after{content:'';position:absolute;width:18px;height:18px;border-color:#d0a76e}.creator-panel:before{top:-1px;left:-1px;border-top:1px solid;border-left:1px solid}.creator-panel:after{bottom:-1px;right:-1px;border-bottom:1px solid;border-right:1px solid}.panel-heading{display:flex;justify-content:space-between;align-items:flex-start}.panel-heading .eyebrow{margin-bottom:5px;font-size:8px}.panel-heading h2{font:normal 19px 'Marcellus',serif;margin:0;letter-spacing:.02em}.step{font:10px 'DM Mono',monospace;color:#e1bd83}.step span{color:#77716a}.creation-layout{display:grid;grid-template-columns:104px 1fr;gap:19px;margin:17px 0 15px}.portrait-frame{position:relative;border:1px solid rgba(220,192,145,.23);height:133px;background:radial-gradient(ellipse at 50% 65%,#5f4936,#241f20 67%,#191920);display:flex;align-items:center;justify-content:center;overflow:hidden}.portrait-frame canvas{width:96px;height:120px;image-rendering:pixelated}.portrait-label{position:absolute;bottom:5px;font:7px 'DM Mono',monospace;letter-spacing:.13em;color:#d0b98e;text-shadow:0 1px 3px #000}.field-label{display:block;font:8px 'DM Mono',monospace;letter-spacing:.16em;color:#a39b90;margin-bottom:6px}.creation-controls input{height:29px;width:100%;background:#121219;border:1px solid rgba(222,198,157,.19);outline:none;padding:0 9px;color:#f1e8d7;font:12px 'DM Sans',sans-serif}.creation-controls input:focus{border-color:#d0a76e}.class-label{margin:12px 0 6px}.class-options{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.class-card{position:relative;display:flex;align-items:center;gap:6px;text-align:left;min-width:0;height:45px;padding:5px 5px;background:rgba(13,13,19,.76);border:1px solid rgba(219,201,170,.15);cursor:pointer;transition:.18s}.class-card:hover{border-color:rgba(226,188,128,.5)}.class-card.selected{background:rgba(122,89,50,.2);border-color:#c49b66}.class-icon{width:20px;text-align:center;color:#e0bb82;font-size:16px}.class-icon.bow{font-size:22px}.class-card b,.class-card small{display:block;white-space:nowrap}.class-card b{font-size:9px;font-weight:600}.class-card small{font-size:7px;color:#928d85;margin-top:3px}.class-card .check{display:none;position:absolute;right:4px;top:3px;color:#e5c28e;font-size:8px}.class-card.selected .check{display:block}.panel-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid rgba(223,201,167,.13);padding-top:12px}.panel-footer p{margin:0;color:#aaa49a;font:7px 'DM Mono',monospace;letter-spacing:.08em;white-space:nowrap}.keycap{color:#e2c28f;border:1px solid rgba(218,189,145,.32);padding:3px 4px;margin-right:3px;font-size:7px}.begin-button{height:38px;min-width:169px;padding:0 13px;background:#c28f51;color:#211912;border:1px solid #e0b576;font:600 9px 'DM Mono',monospace;letter-spacing:.11em;cursor:pointer;box-shadow:inset 0 1px rgba(255,255,255,.2);transition:.2s}.begin-button span{font-size:16px;margin-left:12px;vertical-align:-1px}.begin-button:hover{background:#e2b875;transform:translateY(-1px);box-shadow:0 5px 20px #c28f5140}.title-foot{display:flex;justify-content:space-between;color:#847e76;font:7px 'DM Mono',monospace;letter-spacing:.13em}.hidden{display:none!important}
#game-ui{position:absolute;inset:0;z-index:4;pointer-events:none}.hud-top{position:absolute;top:0;left:0;right:0;height:72px;display:flex;align-items:center;padding:0 30px;background:linear-gradient(#121118d9,transparent);gap:36px}.hero-status{display:flex;align-items:center;gap:10px;width:188px}.avatar-mini{width:34px;height:34px;border:1px solid #c7a773;background:#282127;color:#e4bd7d;display:grid;place-items:center;font:17px 'Marcellus',serif}.status-copy b,.status-copy span{display:block}.status-copy b{font:11px 'DM Mono',monospace;letter-spacing:.11em}.status-copy span{font:7px 'DM Mono',monospace;color:#a39a8b;margin-top:4px;letter-spacing:.08em}.health-block{width:220px}.health-label{display:flex;justify-content:space-between;color:#c7c0b5;font:8px 'DM Mono',monospace;letter-spacing:.1em;margin-bottom:6px}.health-label b{color:#ead7b7;font-weight:400}.bar{height:5px;background:#40343a;border:1px solid #655047}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#9c5145,#e89a70);transition:width .25s}.relic-counter{display:flex;align-items:center;gap:10px;margin-left:auto;margin-right:184px}.relic-gem{color:#f2c77f;font-size:22px;text-shadow:0 0 12px #ecaa55}.relic-counter b,.relic-counter small{display:block}.relic-counter b{font:12px 'DM Mono',monospace;color:#f0d8ae}.relic-counter small{font:7px 'DM Mono',monospace;color:#a49b8e;letter-spacing:.1em;margin-top:3px}.hud-right{position:absolute;right:29px;top:83px;display:flex;flex-direction:column;align-items:center;gap:10px}.map-frame{padding:5px;background:rgba(16,15,20,.78);border:1px solid rgba(222,190,140,.42);box-shadow:0 5px 18px #0006}.map-frame canvas{display:block;width:100px;height:100px;image-rendering:pixelated}.map-frame span{display:block;text-align:center;padding:5px 0 0;font:7px 'DM Mono',monospace;color:#a69c8d;letter-spacing:.13em}.sound-button{pointer-events:auto;background:#18171dbb;border:1px solid #6c5a45;color:#d9bd91;padding:6px 9px;font:10px 'DM Mono',monospace;cursor:pointer}.sound-button span{font-size:7px;letter-spacing:.09em}.hud-bottom{position:absolute;bottom:0;left:0;right:0;min-height:66px;display:flex;align-items:center;justify-content:space-between;padding:10px 30px;background:linear-gradient(transparent,#121118e8);gap:16px}.objective{display:flex;align-items:center;gap:10px}.objective-icon{font-size:20px;color:#e4b979}.objective small,.objective b{display:block}.objective small{font:7px 'DM Mono',monospace;color:#b59b75;letter-spacing:.14em}.objective b{font-size:10px;font-weight:500;margin-top:4px;color:#e5ddd1}.controls-hint{display:flex;align-items:center;gap:15px;font:7px 'DM Mono',monospace;letter-spacing:.08em;color:#aaa49b}.controls-hint span{display:flex;align-items:center;gap:3px}.controls-hint kbd{font:8px 'DM Mono',monospace;color:#e6d3af;border:1px solid #81715a;background:#29252a;padding:3px 4px}.toast{position:absolute;top:17%;left:50%;transform:translate(-50%,-6px);opacity:0;padding:9px 16px;background:#17161ddd;border:1px solid #be9a67;color:#e9d8bb;font:9px 'DM Mono',monospace;letter-spacing:.08em;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.combat-flash{position:absolute;inset:0;border:0 solid rgba(183,53,43,0);transition:border .1s}.combat-flash.hit{border:10px solid rgba(183,53,43,.38)}.modal{pointer-events:auto;position:absolute;inset:0;display:grid;place-items:center;background:rgba(9,8,13,.68);backdrop-filter:blur(4px)}.modal-card{text-align:center;width:min(380px,calc(100vw - 40px));padding:35px 30px;background:#1a181e;border:1px solid #9a7951;box-shadow:0 20px 80px #000b}.modal-card .eyebrow{margin:0 0 10px}.modal-card h2{font:normal 29px 'Marcellus',serif;letter-spacing:.1em;margin:0 0 10px;color:#e9d1aa}.modal-card p:not(.eyebrow){color:#aaa195;font-size:12px;margin:0 0 22px}.modal-card .begin-button{width:100%}.text-button{display:block;background:none;border:0;color:#a69d91;font:8px 'DM Mono',monospace;letter-spacing:.12em;margin:18px auto 0;cursor:pointer}.start-hint{position:absolute;z-index:3;bottom:80px;left:50%;transform:translateX(-50%);padding:8px 13px;background:#17151dba;border:1px solid #8e714c;color:#e4c38f;font:9px 'DM Mono',monospace;letter-spacing:.12em;animation:pulse 2s infinite}@keyframes pulse{50%{opacity:.55}}.start-hint span{margin-right:6px}.touch-controls{display:none;pointer-events:auto;position:absolute;bottom:80px;left:18px;right:18px;align-items:flex-end;justify-content:space-between}.dpad{display:flex;flex-direction:column;align-items:center;gap:2px}.dpad div{display:flex;gap:2px}.dpad button,.touch-action{width:39px;height:37px;border:1px solid #c9a77577;background:#17151ddd;color:#e4c18c;font-size:13px;border-radius:4px;touch-action:none}.touch-action{width:51px;height:51px;border-radius:50%;font-size:18px;margin:0 5px 7px}.touch-action small{display:block;font:6px 'DM Mono',monospace}.touch-action.dodge{margin-left:auto;background:#25202a}
@media(max-width:760px){.screen{padding:18px 22px}.brand{gap:7px;font-size:8px}.brand-small{font-size:6px}.brand-line{width:18px}.title-copy{top:12%;left:22px}.title-copy h1{font-size:48px}.subtitle{font-size:12px}.intro{font-size:10px}.creator-panel{left:22px;bottom:7%;width:min(430px,calc(100vw - 44px));padding:14px 14px 11px}.panel-heading h2{font-size:16px}.creation-layout{grid-template-columns:82px 1fr;gap:11px;margin:12px 0}.portrait-frame{height:118px}.portrait-frame canvas{width:80px;height:100px}.class-options{gap:3px}.class-card{height:43px;gap:2px;padding:4px 3px}.class-icon{width:16px;font-size:13px}.class-card b{font-size:8px}.class-card small{font-size:6px}.panel-footer p{font-size:6px}.keycap{font-size:6px;padding:3px 2px}.begin-button{min-width:145px;font-size:8px;padding:0 8px}.title-foot{font-size:6px}.hud-top{height:62px;padding:0 12px;gap:9px}.hero-status{width:auto;gap:6px}.avatar-mini{width:29px;height:29px}.status-copy b{font-size:9px}.status-copy span{font-size:6px}.health-block{width:min(28vw,150px)}.health-label{font-size:6px}.relic-counter{margin:0 100px 0 auto;gap:5px}.relic-gem{font-size:16px}.relic-counter b{font-size:9px}.relic-counter small{font-size:6px}.hud-right{top:70px;right:10px}.map-frame{padding:3px}.map-frame canvas{width:76px;height:76px}.map-frame span{font-size:6px}.sound-button{font-size:8px;padding:4px}.sound-button span{display:none}.hud-bottom{min-height:57px;padding:8px 12px;align-items:flex-start}.objective-icon{font-size:16px}.objective small{font-size:6px}.objective b{font-size:8px;max-width:170px}.controls-hint{display:none}.touch-controls{display:flex}.toast{top:13%;font-size:8px}.start-hint{bottom:80px}.title-foot span:first-child{max-width:70%}}
@media(max-height:650px) and (min-width:761px){.title-copy{top:10%}.creator-panel{bottom:5%;padding:14px 18px 11px}.creation-layout{margin:10px 0}.portrait-frame{height:112px}.portrait-frame canvas{height:100px}.title-foot{font-size:6px}}
@media(max-width:390px){.panel-footer p{display:none}.class-card{height:40px}.creation-layout{grid-template-columns:72px 1fr}.portrait-frame{height:112px}.class-card small{font-size:5px}.title-copy h1{font-size:42px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#scene'), ctx = canvas.getContext('2d');
  const portrait = document.querySelector('#portrait'), pctx = portrait.getContext('2d');
  const minimap = document.querySelector('#minimap'), mctx = minimap.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const rand = (a,b) => Math.random()*(b-a)+a;
  const pick = (a) => a[Math.floor(Math.random()*a.length)];
  const palettes = [
    {floor:'#37343a',floor2:'#3c383d',wall:'#534b49',side:'#373139',edge:'#776658',glow:'#d88b49',mist:'#88717b'},
    {floor:'#34383b',floor2:'#383e40',wall:'#4b5250',side:'#303638',edge:'#67746b',glow:'#8bd7c6',mist:'#638f8b'},
    {floor:'#3c3438',floor2:'#41373b',wall:'#55444a',side:'#382f38',edge:'#80616a',glow:'#d36e8f',mist:'#95657e'}
  ];
  const outfits = {Warden:{coat:'#687a78',trim:'#bc9161',hair:'#b08b65'},Ranger:{coat:'#75825a',trim:'#c58b54',hair:'#d0b38b'},Arcanist:{coat:'#66628a',trim:'#d8b772',hair:'#aaa1c1'}};
  let W=480,H=270,px=0,py=0,tick=0,selectedClass='Warden',heroName='Ash',gameState='title';
  let dungeon=[],size=41,player,enemies=[],relics=[],exitCell=null,palette=palettes[0],cameraShake=0,toastTimer=0,attackTimer=0,dodgeTimer=0,damageTimer=0,paused=false,moveKeys={},touch={},soundOn=true,audioCtx=null,lastTime=0,stars=[];

  function resize(){
    W=Math.max(300,Math.round(innerWidth/2.5)); H=Math.max(190,Math.round(innerHeight/2.5));
    canvas.width=W; canvas.height=H;
    ctx.imageSmoothingEnabled=false;
  }
  addEventListener('resize',resize); resize();
  function carve(x,y){if(x>=0&&y>=0&&x<size&&y<size)dungeon[y][x]=1;}
  function generate(){
    size=41; dungeon=Array.from({length:size},()=>Array(size).fill(0));
    const stack=[[1,1]]; carve(1,1);
    while(stack.length){let [x,y]=stack[stack.length-1],opts=[];for(const [dx,dy] of [[2,0],[-2,0],[0,2],[0,-2]])if(x+dx>0&&y+dy>0&&x+dx<size-1&&y+dy<size-1&&!dungeon[y+dy][x+dx])opts.push([dx,dy]);if(!opts.length){stack.pop();continue}let [dx,dy]=pick(opts);carve(x+dx/2,y+dy/2);carve(x+dx,y+dy);stack.push([x+dx,y+dy]);}
    for(let i=0;i<64;i++){let x=2+Math.floor(Math.random()*(size-4)),y=2+Math.floor(Math.random()*(size-4));if(dungeon[y][x]&&Math.random()<.54){if(Math.random()<.5)carve(x+1,y);else carve(x,y+1)}}
    // Small chambers are cut into the wandering corridors.
    for(let i=0;i<13;i++){let x=3+Math.floor(Math.random()*(size-7)),y=3+Math.floor(Math.random()*(size-7));if(dungeon[y][x])for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(Math.random()>.13)carve(x+dx,y+dy)}
    const start={x:1,y:1},dist=distances(start);let floors=[];for(let y=1;y<size-1;y++)for(let x=1;x<size-1;x++)if(dungeon[y][x])floors.push({x,y,d:dist[y][x]||0});
    const far=[...floors].sort((a,b)=>b.d-a.d);exitCell=far[0];
    player={x:1.5,y:1.5,hp:100,maxHp:100,faceX:1,faceY:0,speed:3.05,invuln:0,walk:0,relics:0,kills:0};
    const relicSpots=[];for(const f of far){if(f.d<12)break;if(relicSpots.every(r=>Math.hypot(f.x-r.x,f.y-r.y)>8))relicSpots.push(f);if(relicSpots.length===3)break}
    relics=relicSpots.map((c,i)=>({...c,got:false,phase:i*2.2}));
    const used=new Set([`1,1`,`${exitCell.x},${exitCell.y}`,...relicSpots.map(r=>`${r.x},${r.y}`)]);
    enemies=[];for(let i=0;i<Math.min(11,Math.floor(floors.length/30));i++){let c=pick(floors.filter(f=>f.d>7&&!used.has(`${f.x},${f.y}`)));if(!c)continue;used.add(`${c.x},${c.y}`);enemies.push({x:c.x+.5,y:c.y+.5,hp:2,max:2,phase:rand(0,7),speed:rand(.45,.7),alert:false,hit:0})}
    palette=pick(palettes);stars=Array.from({length:35},()=>({x:rand(0,W),y:rand(0,H),a:rand(.1,.55),s:rand(.3,1)}));
  }
  function distances(start){let out=Array.from({length:size},()=>Array(size).fill(-1)),q=[start];out[start.y][start.x]=0;for(let i=0;i<q.length;i++){const c=q[i];for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let x=c.x+dx,y=c.y+dy;if(x>=0&&y>=0&&x<size&&y<size&&dungeon[y][x]&&out[y][x]<0){out[y][x]=out[c.y][c.x]+1;q.push({x,y})}}}return out}
  function isFloor(x,y){return x>=0&&y>=0&&x<size&&y<size&&dungeon[Math.floor(y)]?.[Math.floor(x)]===1}
  function drawPortrait(){pctx.clearRect(0,0,96,120);let o=outfits[selectedClass];pctx.fillStyle='#342b2b';pctx.fillRect(10,82,76,38);pctx.fillStyle='#594334';pctx.fillRect(17,91,62,29);pctx.fillStyle='#211c21';pctx.fillRect(31,22,34,32);pctx.fillStyle=o.hair;pctx.fillRect(30,18,36,19);pctx.fillRect(28,26,6,16);pctx.fillRect(62,23,5,20);pctx.fillStyle='#d3ab82';pctx.fillRect(34,30,28,30);pctx.fillRect(30,37,5,10);pctx.fillRect(61,37,5,10);pctx.fillStyle='#30252a';pctx.fillRect(39,42,4,3);pctx.fillRect(54,42,4,3);pctx.fillStyle='#8c5549';pctx.fillRect(45,53,8,2);pctx.fillStyle=o.coat;pctx.fillRect(27,62,42,32);pctx.fillRect(20,66,12,25);pctx.fillRect(64,66,12,25);pctx.fillStyle=o.trim;pctx.fillRect(45,62,5,31);pctx.fillRect(30,74,35,3);pctx.fillStyle='#25232a';pctx.fillRect(31,92,14,20);pctx.fillRect(51,92,14,20);pctx.fillStyle='#8b765f';pctx.fillRect(27,110,21,5);pctx.fillRect(49,110,21,5);pctx.fillStyle='rgba(243,185,112,.25)';pctx.fillRect(0,0,96,4)}
  function setClass(c){selectedClass=c;document.querySelectorAll('.class-card').forEach(b=>b.classList.toggle('selected',b.dataset.class===c));drawPortrait()}
  document.querySelectorAll('.class-card').forEach(b=>b.addEventListener('click',()=>setClass(b.dataset.class)));
  $('#hero-name').addEventListener('input',e=>heroName=e.target.value.trim().slice(0,14)||'Ash');drawPortrait();

  function tileDiamond(x,y,w,h,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-h/2);ctx.lineTo(x+w/2,y);ctx.lineTo(x,y+h/2);ctx.lineTo(x-w/2,y);ctx.closePath();ctx.fill()}
  function project(x,y,cx,cy,tw,th){return {x:cx+(x-y)*tw,y:cy+(x+y)*th}}
  function drawFloor(tx,ty,sx,sy,tw,th){
    let checker=(tx*13+ty*7)%7===0;tileDiamond(sx,sy,tw*2,th*2,checker?palette.floor2:palette.floor);
    if((tx*3+ty*5)%29===2){ctx.fillStyle='#66584d';ctx.fillRect(sx-2,sy-1,4,1);ctx.fillRect(sx+1,sy+1,2,1)}
    if((tx*11+ty*3)%53===9){ctx.fillStyle='#242228';ctx.fillRect(sx-4,sy,1,1);ctx.fillRect(sx+3,sy-2,2,1)}
  }
  function drawWall(sx,sy,tw,th,hash){
    const hh=16+((hash*13)%4);ctx.fillStyle=palette.side;ctx.beginPath();ctx.moveTo(sx-tw,sy);ctx.lineTo(sx,sy+th);ctx.lineTo(sx,sy+th+hh);ctx.lineTo(sx-tw,sy+hh);ctx.closePath();ctx.fill();
    ctx.fillStyle=hash%3===0?'#423a3c':'#494143';ctx.beginPath();ctx.moveTo(sx,sy+th);ctx.lineTo(sx+tw,sy);ctx.lineTo(sx+tw,sy+hh);ctx.lineTo(sx,sy+th+hh);ctx.closePath();ctx.fill();
